src='''from collections import defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx,ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx,ny))
                        stack.append((nx,ny))
            components.append((color, cells))
    sizes = defaultdict(list)
    for color, cells in components:
        sizes[color].append(len(cells))
    out = [row[:] for row in grid]
    for color, cells in components:
        if len(cells) == 1 and any(size > 1 for size in sizes[color]):
            r, c = cells[0]
            out[r][c] = 0
    return out
'''
